<script setup>
import { computed, ref } from 'vue'

const props=defineProps({leftLabel:{type:String,default:''},rightLabel:{type:String,default:''},leftAction:{type:String,default:''},rightAction:{type:String,default:''},leftDisabled:{type:Boolean,default:false},rightDisabled:{type:Boolean,default:false},disabled:{type:Boolean,default:false},shell:{type:String,default:'driver'},activeState:{type:String,default:''}})
const emit=defineEmits(['swipe'])
