function down(e){if(props.disabled||e.button!==undefined&&e.button!==0)return;activePointer.value=e.pointerId;startX.value=e.clientX;dragDirection.value=1;setProgress(0,e.currentTarget.clientWidth);capturing.value=true;dragging.value=true;e.currentTarget.setPointerCapture?.(e.pointerId)}
function move(e){if(!capturing.value||e.pointerId!==activePointer.value)return;const w=Math.max(1,e.currentTarget.clientWidth),dx=e.clientX-startX.value;dragDirection.value=dx<0?-1:1;const distance=isDual.value?Math.abs(dx)/(w/2)*100:Math.abs(dx)/w*100;setProgress(distance,w,dragDirection.value)}
function finish(e){if(!capturing.value||e.pointerId!==activePointer.value)return;const dx=e.clientX-startX.value,left=dx<0,threshold=progress.value>=70,action=left?props.leftAction:props.rightAction,blocked=props.disabled||(left?props.leftDisabled:props.rightDisabled);capturing.value=false;dragging.value=false;activePointer.value=null;e.currentTarget.releasePointerCapture?.(e.pointerId);if(threshold&&action&&!blocked){setProgress(100,e.currentTarget.clientWidth,left?-1:1);emit('swipe',action);setTimeout(()=>setProgress(0,e.currentTarget.clientWidth),140)}else setProgress(0,e.currentTarget.clientWidth)}
</script>
<template><div class="kfe-swipe-bar" :class="{'is-disabled':disabled,'is-dual':isDual,'is-dual-left':isDual&&dragDirection<0,'is-dragging':dragging}" :data-shell="shell" :data-state="activeState" :style="barStyle" :aria-disabled="disabled" aria-valuemin="0" aria-valuemax="100" :aria-valuenow="Math.round(progress)" role="slider" :aria-label="[leftText,rightText].filter(Boolean).join(' or ')" @pointerdown="down" @pointermove="move" @pointerup="finish" @pointercancel="finish"><span class="kfe-swipe-progress" aria-hidden="true"></span><span class="kfe-swipe-edge-glow" aria-hidden="true"></span><span v-if="leftText" class="kfe-swipe-left" :class="{'is-action-disabled':leftDisabled}"><b>←</b>{{leftText}}</span><span v-if="rightText" class="kfe-swipe-right" :class="{'is-action-disabled':rightDisabled}">{{rightText}}<b>→</b></span><span class="kfe-swipe-label-overlay" aria-hidden="true">{{leftText&&rightText?'Swipe to act':leftText||rightText}}</span><span class="kfe-swipe-chevrons" aria-hidden="true">›››</span><span class="kfe-swipe-handle" aria-hidden="true"><i></i>›</span><span class="kfe-swipe-gps" aria-hidden="true">GPS • {{new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}}</span></div></template>

<style>
.kfe-swipe-bar{--swipe-accent:var(--kfe-ui-accent,#38bdf8);--swipe-bg:var(--kfe-ui-bg,#0f172a);--swipe-surface:var(--kfe-ui-surface,#111827);position:relative;min-height:78px!important;height:78px!important;border:1px solid color-mix(in srgb,var(--swipe-accent) 48%,var(--kfe-ui-border,#ffffff33))!important;border-radius:24px!important;background:linear-gradient(135deg,color-mix(in srgb,var(--swipe-surface) 88%,var(--swipe-accent) 12%),color-mix(in srgb,var(--swipe-bg) 82%,var(--swipe-accent) 18%))!important;box-shadow:0 18px 42px color-mix(in srgb,var(--swipe-accent) 20%,transparent),inset 0 1px 0 color-mix(in srgb,white 18%,transparent),inset 0 -1px 0 color-mix(in srgb,var(--swipe-accent) 22%,transparent)!important;overflow:hidden}
