.kfe-swipe-bar[data-shell="delivery"]{--swipe-accent:color-mix(in srgb,var(--kfe-ui-accent,#34d399) 78%,#34d399)}
.kfe-swipe-bar[data-shell="driver"]{--swipe-accent:color-mix(in srgb,var(--kfe-ui-accent,#38bdf8) 78%,#38bdf8)}
.kfe-swipe-bar[data-state="close"]{--swipe-accent:color-mix(in srgb,var(--kfe-ui-accent,#fb7185) 72%,#fb7185)}
